function ProductCard({ p, go }: { p:typeof products[number]; go:(s:Screen)=>void }) { return <Card><div className="flex items-start justify-between gap-3"><div><h3 className="font-semibold">{p.name}</h3><p className="text-sm text-muted-foreground">{p.type}</p></div><button className="rounded-lg p-1 hover:bg-muted"><MoreHorizontal size={18}/></button></div><div className="mt-4 flex flex-wrap gap-2"><ProductStatusBadge status={p.status}/><Badge tone="blue">{p.modules} módulos</Badge></div><div className="mt-4 grid grid-cols-2 gap-2 text-sm"><div className="rounded-lg bg-muted p-3"><p className="text-xs text-muted-foreground">Saúde</p><p className="font-semibold">{p.score}</p></div><div className="rounded-lg bg-muted p-3"><p className="text-xs text-muted-foreground">Atividade</p><p className="truncate font-semibold">Hoje</p></div></div><p className="mt-4 text-sm text-muted-foreground">{p.last}</p><Button primary onClick={()=>go(p.modules?"product":"empty")}><ExternalLink size={15}/>Abrir produto</Button></Card> }
function ProductsList({ go }: { go:(s:Screen)=>void }) { const [view,setView]=useState<"grid"|"list">("grid"), [q,setQ]=useState(""), [sf,setSf]=useState<ProductStatus|"todos">("todos"); const filtered=products.filter(p=>p.name.toLowerCase().includes(q.toLowerCase())&&(sf==="todos"||p.status===sf)); const statuses:Array<ProductStatus|"todos">=["todos","Ativo","Pendente","Arquivado","Sem módulos"]; return <><PageHeader title="Produtos" module="Produtos" desc="Administre os produtos digitais deste tenant." go={go}><Button onClick={()=>setView(view==="grid"?"list":"grid")}>{view==="grid"?"Lista":"Grid"}</Button><Button primary onClick={()=>go("create")}><Plus size={15}/>Novo produto</Button></PageHeader><div className="mb-4 space-y-2"><div className="flex items-center gap-2 rounded-xl border border-border bg-card px-3 py-2"><Search size={16}/><input value={q} onChange={e=>setQ(e.target.value)} placeholder="Buscar Maestro, Genesis, WikiDev..." className="w-full bg-transparent text-sm outline-none"/>{q&&<button onClick={()=>setQ("")} className="text-muted-foreground hover:text-foreground"><X size={14}/></button>}</div><div className="flex gap-1.5 overflow-x-auto pb-px">{statuses.map(s=><button key={s} onClick={()=>setSf(s)} className={`whitespace-nowrap rounded-xl border px-3 py-1 text-sm transition ${sf===s?"border-primary bg-primary/5 text-primary font-medium":"border-border bg-card text-muted-foreground hover:bg-muted"}`}>{s==="todos"?"Todos":s}</button>)}</div></div>{filtered.length===0?<EmptyState title="Busca sem resultado" description="Ajuste filtros por tipo, status ou limpe a busca."/>:view==="grid"?<div className="grid gap-4 md:grid-cols-2 xl:grid-cols-3">{filtered.map(p=><ProductCard key={p.name} p={p} go={go}/>)}</div>:<div className="space-y-2">{filtered.map(p=><div key={p.name} className="flex flex-col gap-3 rounded-xl border border-border bg-card p-4 md:flex-row md:items-center md:justify-between"><div><p className="font-semibold">{p.name}</p><p className="text-sm text-muted-foreground">{p.type} · {p.last}</p></div><div className="flex items-center gap-2"><ProductStatusBadge status={p.status}/><Button onClick={()=>go(p.modules?"product":"empty")}>Abrir</Button></div></div>)}</div>}</> }
function CreateProductForm(){const [saving,setSaving]=useState(false),[slug,setSlug]=useState("novo-produto");const handleCreate=()=>{setSaving(true);setTimeout(()=>{setSaving(false);toast.success("Produto criado com sucesso!",{description:`byop/${slug} · 6 módulos iniciais habilitados`});},900);};return <><PageHeader title="Novo Produto" desc="Crie um produto digital com módulos iniciais e identidade operacional."><Button>Cancelar</Button><Button primary onClick={handleCreate}>{saving&&<Loader2 size={15} className="animate-spin"/>}{saving?"Criando...":"Criar produto"}</Button></PageHeader><div className="grid gap-4 xl:grid-cols-[1fr_340px]"><Card><div className="grid gap-4 md:grid-cols-2"><Field label="Nome do produto" value="Maestro Beton"/><Field label="Slug" value={slug} onChange={setSlug}/><SelectLike label="Tipo" value="Site Institucional"/><SelectLike label="Idioma padrão" value="Português (Brasil)"/><div className="md:col-span-2"><Field label="Descrição" value="Produto institucional com conteúdo, formulários, SEO e assets governados." textarea/></div><SelectLike label="Template inicial" value="Produto operacional padrão"/><div><p className="mb-2 text-sm font-medium">Módulos iniciais</p><div className="flex flex-wrap gap-2">{["Conteúdo","Assets","Forms","Analytics","SEO","Workflow"].map(m=><Badge key={m} tone="green">{m}</Badge>)}</div></div></div><div className="mt-4 rounded-xl bg-muted p-3 text-sm"><CheckCircle2 size={16} className="mb-2 text-primary"/>Slug disponível: <b>{slug}</b></div></Card><ProductSummaryPanel slug={slug}/></div></>}
function Field({label,value,onChange,textarea=false}:{label:string;value:string;onChange?:(v:string)=>void;textarea?:boolean}){return <label className="block"><span className="mb-1 block text-sm font-medium">{label}</span>{textarea?<textarea className="min-h-28 w-full rounded-lg border border-border bg-card p-3 text-sm outline-primary" defaultValue={value}/>:<input className="w-full rounded-lg border border-border bg-card p-3 text-sm outline-primary" value={value} onChange={e=>onChange?.(e.target.value)}/>}</label>}
function SelectLike({label,value}:{label:string;value:string}){return <label className="block"><span className="mb-1 block text-sm font-medium">{label}</span><button className="flex w-full items-center justify-between rounded-lg border border-border bg-card p-3 text-sm"><span>{value}</span><ChevronDown size={15}/></button></label>}
function ProductSummaryPanel({slug}:{slug:string}){return <Card><h2 className="text-lg font-semibold">Resumo do produto</h2><p className="mt-2 text-sm text-muted-foreground">BYOP → {slug} → módulos iniciais.</p><div className="mt-4 space-y-3 text-sm"><div className="flex justify-between"><span>Identificador</span><b className="font-mono">byop/{slug}</b></div><div className="flex justify-between"><span>Status inicial</span><Badge tone="amber">Configurando</Badge></div><div className="flex justify-between"><span>Módulos</span><b>6</b></div></div></Card>}
function ProductDashboard({ empty=false, go, viewAsRole="product_manager" }: { empty?:boolean; go:(s:Screen)=>void; viewAsRole?:UserRole }) { if(empty) return <ProductEmpty go={go}/>; const pendencias:[string,Screen][]=[["Revisar conteúdo em aprovação","workflow"],["Configurar SEO da página Home","productSettings"],["Adicionar imagens à galeria","assets"],["Ver respostas do formulário de orçamento","submissions"]]; return <><PageHeader title="Maestro Beton" desc="Cockpit operacional do produto digital: saúde, pendências, módulos e próximos passos." badge="Site Institucional"><Button onClick={()=>go("detail")}>Editar produto</Button><Button onClick={()=>go("modules")}>Ver módulos</Button><Button primary><ExternalLink size={15}/>Preview público</Button></PageHeader><div className="grid gap-4 xl:grid-cols-[1fr_360px]"><div className="space-y-4"><div className="grid gap-3 sm:grid-cols-2 xl:grid-cols-4"><KPIWidget label="Status do produto" value="Saudável" detail="Sem incidentes críticos" onClick={()=>go("productHealth")}/><KPIWidget label="Módulos habilitados" value="6" detail="1 dependência pendente" onClick={()=>go("modules")}/><KPIWidget label="Conteúdos publicados" value="42" detail="+3 na semana" onClick={()=>go("contentList")}/><KPIWidget label="Em revisão" value="7" detail="2 acima do SLA" onClick={()=>go("workflow")}/><KPIWidget label="Formulários" value="89" detail="12 não lidos" onClick={()=>go("submissions")}/><KPIWidget label="Conversão estimada" value="5.2%" detail="+0.8 p.p." onClick={()=>go("analytics")}/><KPIWidget label="Assets recentes" value="18" detail="Galeria atualizada" onClick={()=>go("assets")}/><KPIWidget label="Erro parcial" value="—" detail="" error onClick={()=>go("analyticsStates")}/></div><QuickActions go={go} viewAsRole={viewAsRole}/><ModuleCatalog compact/></div><Card><h2 className="mb-3 text-lg font-semibold">Atividade recente</h2><OperationalTimeline go={go}/><h2 className="mb-3 mt-5 text-lg font-semibold">Pendências</h2>{pendencias.map(([label,screen])=><button key={label} onClick={()=>go(screen)} className="mb-2 flex w-full items-center justify-between rounded-xl border border-border p-3 text-left text-sm transition hover:border-primary/30 hover:bg-muted"><span>{label}</span><ChevronRight size={14} className="shrink-0 text-muted-foreground"/></button>)}</Card></div></> }
