function ProductDetail(){return <><PageHeader title="Maestro Beton" module="Visão Geral" desc="Dados administrativos, módulos, equipe, domínios futuros e auditoria recente."><Button>Editar</Button><Button primary>Salvar visão</Button></PageHeader><div className="mb-4 flex gap-2 overflow-auto pb-1">{["Visão Geral","Módulos","Conteúdo","Assets","Forms","Analytics","Graph","Configurações"].map((t,i)=><button key={t} className={`whitespace-nowrap rounded-lg border px-3 py-2 text-sm ${i===0?"border-primary bg-primary text-white":"border-border bg-card"}`}>{t}</button>)}</div><div className="grid gap-4 xl:grid-cols-[1fr_360px]"><Card><h2 className="mb-4 text-lg font-semibold">Dados gerais</h2><div className="grid gap-3 md:grid-cols-2">{[["Status","Ativo"],["Tipo","Site Institucional"],["Slug","maestro-beton"],["Idioma","pt-BR"],["Descrição","Produto institucional governado"],["Módulos","Conteúdo, Assets, Forms, Analytics"]].map(r=><div key={r[0]} className="rounded-xl bg-muted p-3"><p className="text-xs text-muted-foreground">{r[0]}</p><p className="font-medium">{r[1]}</p></div>)}</div></Card><Card><h2 className="mb-3 text-lg font-semibold">Auditoria recente</h2><OperationalTimeline go={go}/></Card></div></>}
function ProductEmpty({ go }:{go:(s:Screen)=>void}){return <><PageHeader title="Conecta Talentos" module="Dashboard" desc="Produto recém-criado aguardando capacidades iniciais." badge="Sem módulos"><Button>Editar dados do produto</Button><Button primary onClick={()=>go("modules")}>Habilitar módulos</Button></PageHeader><EmptyState title="Este produto ainda não possui módulos habilitados." description="Escolha as capacidades iniciais para começar a operar este produto digital."/><div className="mt-4 grid gap-3 md:grid-cols-3">{["Portal: Conteúdo + Forms + SEO","SaaS: Analytics + Workflow","Knowledge Base: Conteúdo + Graph"].map(s=><Card key={s}><p className="font-medium">{s}</p><p className="text-sm text-muted-foreground">Sugestão por tipo de produto.</p></Card>)}</div></>}
function ModuleCatalog({ compact=false }:{compact?:boolean}){return <div className={compact?"":""}>{!compact&&<PageHeader title="Catálogo de Módulos" module="Módulos" desc="Catálogo operacional de capacidades da plataforma. Não é loja; é controle de operação."><Button>Loading state</Button><Button primary>Habilitar selecionados</Button></PageHeader>}<div className="grid gap-4 md:grid-cols-2 xl:grid-cols-3">{modules.slice(0,compact?6:modules.length).map(([Icon,name,desc,state,maturity,dep,impact])=><ModuleCard key={name} Icon={Icon} name={name} desc={desc} state={state as ModuleState} maturity={maturity} dep={dep} impact={impact}/>)}</div></div>}
function ModuleCard({Icon,name,desc,state,maturity,dep,impact}:any){const tone=state==="habilitado"?"green":state==="dependência"?"amber":state==="sem permissão"?"red":"neutral"; const cta=state==="habilitado"?"Abrir":state==="desabilitado"?"Habilitar":state==="dependência"?"Resolver dependência":state==="sem permissão"?"Sem permissão":"Ver roadmap"; return <Card><div className="flex items-start justify-between"><Icon size={20} className="text-primary"/><Badge tone={tone}>{state}</Badge></div><h3 className="mt-4 font-semibold">{name}</h3><p className="mt-1 text-sm text-muted-foreground">{desc}</p><div className="mt-4 space-y-2 text-xs text-muted-foreground"><p><b>Dependências:</b> {dep}</p><p><b>Impacto:</b> {impact}</p></div><div className="mt-4 flex items-center justify-between"><Badge tone="blue">{maturity}</Badge><Button>{cta}</Button></div></Card>}

