function ContentStatusBadge({status}:{status:string}){return <Badge tone={status==="Published"?"green":status==="In Review"?"amber":status==="Draft"?"blue":"neutral"}>{status}</Badge>}
function EditorialDashboardWidget({label,value,detail}:{label:string;value:string;detail:string}){return <KPIWidget label={label} value={value} detail={detail}/>}
