function ReportGrid(){const reports=[["Relatório mensal do produto","Resumo executivo-operacional do produto.","Junho","PDF","pronto","hoje"],["Performance de conteúdo","Páginas, SEO e publicações.","30 dias","CSV","gerando","agora"],["Conversões de formulários","Leads, origem e resposta.","7 dias","XLSX","pronto","ontem"],["Saúde do produto","Pendências por módulo.","atual","PDF","sem dados suficientes","—"],["Auditoria editorial","Fluxo de revisão e publicação.","mês","PDF","erro","2 dias"],["SEO e acessibilidade","Alt text, metas e oportunidades.","30 dias","PDF","pronto","hoje"]];return <><PageHeader title="Reports" module="Analytics" desc="Central de relatórios implementáveis e rastreáveis." badge="Relatórios"><Button primary>Gerar relatório</Button></PageHeader><div className="grid gap-4 md:grid-cols-2 xl:grid-cols-3">{reports.map(r=><ReportCard key={r[0]} r={r}/>)}</div></>}
function TrendCard({type,text,metric,severity,go}:{type:string;text:string;metric:string;severity:string;go?:(s:Screen)=>void}){const dest:Screen=severity==="positiva"?"contentAnalytics":severity==="alta"?"analytics":"analytics"; return <Card onClick={()=>go?.(dest)}><div className="flex justify-between"><Badge tone={severity==="alta"?"amber":severity==="positiva"?"green":"blue"}>{type}</Badge><span className="font-mono text-xs text-muted-foreground">{metric}</span></div><p className="mt-4 font-medium">{text}</p><p className="mt-2 text-sm text-muted-foreground">Ação recomendada: {severity==="positiva"?"ampliar aprendizado":"investigar e corrigir"}.</p><Button onClick={e=>{e.stopPropagation();go?.(dest);}}>Executar ação</Button></Card>}
function TrendCards({go}:{go:(s:Screen)=>void}){const cards=[["Crescimento","Página Galeria gerou 42% mais interação esta semana.","+42%","positiva"],["Queda","Formulário de orçamento teve queda de conversão.","-6%","alta"],["Estabilidade","Tráfego direto permaneceu estável no período.","0.4%","neutra"],["Anomalia","Pico de visitas sem aumento proporcional de leads.","3x","alta"],["Oportunidade","Assets sem alt text podem prejudicar SEO.","18 assets","alta"],["Atenção","Conteúdo Sobre o Maestro não é atualizado há 45 dias.","45 dias","alta"]];return <><PageHeader title="Trend Cards" module="Analytics" desc="Tendências e insights operacionais que geram ação." badge="Insights" go={go}><Button>Marcar revisado</Button></PageHeader><div className="grid gap-4 md:grid-cols-2 xl:grid-cols-3">{cards.map(c=><TrendCard key={c[0]} type={c[0]} text={c[1]} metric={c[2]} severity={c[3]} go={go}/>)}</div></>}
function PartialAnalyticsError(){return <div className="rounded-xl border border-destructive/20 bg-[#FDEBE8] p-3 text-sm text-destructive">Alguns widgets carregaram, mas canais pagos estão temporariamente indisponíveis.</div>}
function AnalyticsEmptyState(){return <EmptyState title="Este produto ainda não possui dados suficientes." description="Assim que o produto receber visitas, formulários ou publicações, os indicadores aparecerão aqui."/>}
function AnalyticsStates(){return <><PageHeader title="Estados Analytics" module="Analytics" desc="Empty, loading, erro e erro parcial do módulo." badge="Estados"><Button>Tentar novamente</Button></PageHeader><div className="grid gap-4 xl:grid-cols-2"><AnalyticsEmptyState/><Card><h2 className="mb-3 text-lg font-semibold">Loading</h2><SkeletonLines/><div className="mt-3"><SkeletonLines/></div></Card><Card><h2 className="mb-3 text-lg font-semibold">Error</h2><div className="rounded-xl border border-destructive/20 bg-[#FDEBE8] p-4 text-sm text-destructive">Não foi possível carregar os dados de analytics.<div className="mt-3"><Button>Tentar novamente</Button></div></div></Card><Card><h2 className="mb-3 text-lg font-semibold">Partial Error</h2><PartialAnalyticsError/></Card></div></>}

