function getPasswordStrength(pwd: string): "fraca" | "média" | "forte" { if(pwd.length<8) return "fraca"; if(pwd.length>=12&&/\d/.test(pwd)&&/[!@#$%^&*]/.test(pwd)) return "forte"; if(pwd.length>=8&&/\d/.test(pwd)) return "média"; return "fraca"; }

function PasswordStrengthBar({ password }: { password: string }) { const s=getPasswordStrength(password); const lvl={fraca:1,média:2,forte:3}[s]; const col={fraca:"bg-destructive",média:"bg-[#D97706]",forte:"bg-primary"}[s]; return <div className="mt-1.5"><div className="flex gap-1">{[1,2,3].map(i=><div key={i} className={`h-1.5 flex-1 rounded-full transition-colors duration-200 ${i<=lvl?col:"bg-muted"}`}/>)}</div><p className="mt-1 text-xs text-muted-foreground">Senha {s}</p></div>; }

