function LoginScreen({ onLogin, onForgot, onInvite }: { onLogin:(u:AuthUser,t:TenantOption[],p:Record<string,ProductOption[]>)=>void; onForgot:()=>void; onInvite:()=>void }) {
  const [email,setEmail]=useState(""),[password,setPassword]=useState(""),[showPwd,setShowPwd]=useState(false),[loading,setLoading]=useState(false),[error,setError]=useState<LoginError>("");
  const handleLogin=()=>{ setError(""); setLoading(true); setTimeout(()=>{ setLoading(false); const e=mockUsers[email.toLowerCase().trim()]; if(!e){setError("invalid");return;} if(e.error){setError(e.error);return;} if(e.password!==password){setError("invalid");return;} onLogin(e.user,mockTenantsByUser[e.user.id]||[],mockProductsByUser[e.user.id]||{}); },700); };
  const msgs:Record<LoginError,string>={"":"",invalid:"E-mail ou senha incorretos. Verifique suas credenciais e tente novamente.",blocked:"Esta conta está bloqueada. Entre em contato com o administrador.",expired:"Sua sessão expirou. Faça login novamente para continuar.",server:"Erro no servidor. Tente novamente em instantes."};
  return <div className="flex min-h-screen items-center justify-center bg-background px-4 py-12"><AuthEnvBadge/><AuthCard><AuthLogo/><h1 className="mb-1 text-xl font-semibold tracking-[-.02em]">Entrar na plataforma</h1><p className="mb-6 text-sm text-muted-foreground">Acesse sua conta para continuar.</p><div className="space-y-4"><label className="block"><span className="mb-1 block text-sm font-medium">E-mail</span><input type="email" autoFocus value={email} onChange={e=>setEmail(e.target.value)} placeholder="seu@email.com" className="w-full rounded-lg border border-border bg-card px-3 py-2.5 text-sm outline-none transition focus:border-primary focus:ring-2 focus:ring-primary/10" onKeyDown={e=>e.key==="Enter"&&handleLogin()}/></label><label className="block"><div className="mb-1 flex items-center justify-between"><span className="text-sm font-medium">Senha</span><button type="button" onClick={onForgot} className="text-xs text-muted-foreground transition hover:text-foreground">Esqueci minha senha</button></div><div className="relative"><input type={showPwd?"text":"password"} value={password} onChange={e=>setPassword(e.target.value)} placeholder="••••••••" className="w-full rounded-lg border border-border bg-card px-3 py-2.5 pr-10 text-sm outline-none transition focus:border-primary focus:ring-2 focus:ring-primary/10" onKeyDown={e=>e.key==="Enter"&&handleLogin()}/><button type="button" onClick={()=>setShowPwd(!showPwd)} className="absolute right-3 top-1/2 -translate-y-1/2 text-muted-foreground transition hover:text-foreground">{showPwd?<EyeOff size={16}/>:<Eye size={16}/>}</button></div></label>{error&&<motion.div {...fade} className="rounded-lg border border-destructive/20 bg-[#FDEBE8] p-3 text-sm text-destructive">{msgs[error]}</motion.div>}<button onClick={handleLogin} disabled={loading||!email||!password} className="flex w-full items-center justify-center gap-2 rounded-lg bg-primary py-2.5 text-sm text-primary-foreground transition hover:bg-primary/90 disabled:opacity-50">{loading?<><Loader2 size={16} className="animate-spin"/>Entrando...</>:"Entrar"}</button></div><div className="mt-6 border-t border-border pt-4 text-center text-sm text-muted-foreground">Primeiro acesso? <button onClick={onInvite} className="text-primary transition hover:underline">Ativar convite</button></div><div className="mt-4 rounded-lg bg-muted/60 p-3 text-xs text-muted-foreground"><p className="mb-1 font-medium">Contas de demonstração</p><p>admin@byop.io · pm@byop.io · editor@byop.io</p><p>Senha: <span className="font-mono">senha123</span></p></div></AuthCard></div>;
}

function ForgotPasswordScreen({ onBack, onSent }: { onBack:()=>void; onSent:(email:string)=>void }) {
  const [email,setEmail]=useState(""),[loading,setLoading]=useState(false),[error,setError]=useState(""),[attempts,setAttempts]=useState(0);
  const handleSend=()=>{ if(attempts>=3){setError("rate_limit");return;} setError(""); if(!email.includes("@")){setError("E-mail inválido. Verifique e tente novamente.");return;} setLoading(true); setTimeout(()=>{setLoading(false);setAttempts(a=>a+1);onSent(email);},800); };
  return <div className="flex min-h-screen items-center justify-center bg-background px-4 py-12"><AuthEnvBadge/><AuthCard><AuthLogo/><button onClick={onBack} className="mb-6 flex items-center gap-1.5 text-sm text-muted-foreground transition hover:text-foreground"><ArrowLeft size={15}/>Voltar ao login</button><h1 className="mb-1 text-xl font-semibold tracking-[-.02em]">Recuperar acesso</h1><p className="mb-6 text-sm text-muted-foreground">Informe seu e-mail e enviaremos um link de recuperação de senha.</p><div className="space-y-4"><label className="block"><span className="mb-1 block text-sm font-medium">E-mail</span><input type="email" autoFocus value={email} onChange={e=>setEmail(e.target.value)} placeholder="seu@email.com" className="w-full rounded-lg border border-border bg-card px-3 py-2.5 text-sm outline-none transition focus:border-primary focus:ring-2 focus:ring-primary/10" onKeyDown={e=>e.key==="Enter"&&handleSend()}/></label>{error==="rate_limit"?<div className="rounded-lg border border-[#D97706]/30 bg-[#FBF1DF] p-3 text-sm text-[#8A5A12]">Limite de tentativas atingido. Aguarde alguns minutos antes de tentar novamente.</div>:error?<div className="rounded-lg border border-destructive/20 bg-[#FDEBE8] p-3 text-sm text-destructive">{error}</div>:null}<button onClick={handleSend} disabled={loading||!email} className="flex w-full items-center justify-center gap-2 rounded-lg bg-primary py-2.5 text-sm text-primary-foreground transition hover:bg-primary/90 disabled:opacity-50">{loading?<><Loader2 size={16} className="animate-spin"/>Enviando...</>:"Enviar instruções"}</button></div></AuthCard></div>;
}

function ForgotPasswordSentScreen({ email, onBack, onResend, onResetDemo }: { email:string; onBack:()=>void; onResend:()=>void; onResetDemo?:()=>void }) {
  return <div className="flex min-h-screen items-center justify-center bg-background px-4 py-12"><AuthEnvBadge/><AuthCard><div className="text-center"><div className="mx-auto mb-4 grid h-14 w-14 place-items-center rounded-full bg-[#ede9fe]"><MailCheck size={24} className="text-primary"/></div><h1 className="text-xl font-semibold tracking-[-.02em]">Verifique seu e-mail</h1><p className="mt-2 text-sm text-muted-foreground">Enviamos um link de recuperação para <b>{email}</b>. Se não encontrar, confira sua caixa de spam.</p></div><button onClick={onBack} className="mt-6 flex w-full items-center justify-center gap-2 rounded-lg bg-primary py-2.5 text-sm text-primary-foreground transition hover:bg-primary/90">Voltar ao login</button><button onClick={onResend} className="mt-3 w-full text-center text-sm text-muted-foreground transition hover:text-foreground">Reenviar e-mail</button>{onResetDemo&&<button onClick={onResetDemo} className="mt-2 w-full text-center text-xs text-muted-foreground/60 transition hover:text-muted-foreground">Demo: Abrir tela de redefinição →</button>}</AuthCard></div>;
}

function ResetPasswordScreen({ onSuccess, onBack }: { onSuccess:()=>void; onBack:()=>void }) {
  const [tokenState,setTokenState]=useState<"valid"|"invalid"|"expired">("valid"),[pwd,setPwd]=useState(""),[confirm,setConfirm]=useState(""),[loading,setLoading]=useState(false),[error,setError]=useState(""),[success,setSuccess]=useState(false);
  const handleReset=()=>{ setError(""); if(pwd!==confirm){setError("As senhas não coincidem. Verifique e tente novamente.");return;} if(getPasswordStrength(pwd)==="fraca"){setError("Senha muito fraca. Use ao menos 8 caracteres com números.");return;} setLoading(true); setTimeout(()=>{setLoading(false);setSuccess(true);setTimeout(onSuccess,1500);},800); };
  return <div className="flex min-h-screen items-center justify-center bg-background px-4 py-12"><AuthEnvBadge/><AuthCard><AuthLogo/>{tokenState!=="valid"?<><div className="rounded-lg border border-destructive/20 bg-[#FDEBE8] p-4 text-sm text-destructive">{tokenState==="expired"?"Link expirado. Solicite um novo link de recuperação.":"Link inválido. Verifique o e-mail recebido."}</div><button onClick={onBack} className="mt-4 flex w-full items-center justify-center rounded-lg bg-primary py-2.5 text-sm text-primary-foreground transition hover:bg-primary/90">Solicitar novo link</button></>:success?<motion.div {...fade} className="text-center"><div className="mx-auto mb-4 grid h-14 w-14 place-items-center rounded-full bg-[#ede9fe]"><CheckCircle2 size={24} className="text-primary"/></div><h2 className="font-semibold">Senha redefinida com sucesso!</h2><p className="mt-1 text-sm text-muted-foreground">Redirecionando para o login...</p></motion.div>:<><h1 className="mb-1 text-xl font-semibold tracking-[-.02em]">Definir nova senha</h1><p className="mb-6 text-sm text-muted-foreground">Escolha uma senha segura para sua conta.</p><div className="space-y-4"><label className="block"><span className="mb-1 block text-sm font-medium">Nova senha</span><input type="password" autoFocus value={pwd} onChange={e=>setPwd(e.target.value)} placeholder="••••••••" className="w-full rounded-lg border border-border bg-card px-3 py-2.5 text-sm outline-none transition focus:border-primary focus:ring-2 focus:ring-primary/10"/>{pwd&&<PasswordStrengthBar password={pwd}/>}</label><label className="block"><span className="mb-1 block text-sm font-medium">Confirmar senha</span><input type="password" value={confirm} onChange={e=>setConfirm(e.target.value)} placeholder="••••••••" className="w-full rounded-lg border border-border bg-card px-3 py-2.5 text-sm outline-none transition focus:border-primary focus:ring-2 focus:ring-primary/10"/></label>{error&&<div className="rounded-lg border border-destructive/20 bg-[#FDEBE8] p-3 text-sm text-destructive">{error}</div>}<button onClick={handleReset} disabled={loading||!pwd||!confirm} className="flex w-full items-center justify-center gap-2 rounded-lg bg-primary py-2.5 text-sm text-primary-foreground transition hover:bg-primary/90 disabled:opacity-50">{loading?<><Loader2 size={16} className="animate-spin"/>Salvando...</>:"Salvar nova senha"}</button></div></>}<div className="mt-4 flex gap-1.5 text-xs"><button onClick={()=>setTokenState("valid")} className="flex-1 rounded-lg border border-border bg-muted p-1 text-muted-foreground">válido</button><button onClick={()=>setTokenState("expired")} className="flex-1 rounded-lg border border-border bg-muted p-1 text-muted-foreground">expirado</button><button onClick={()=>setTokenState("invalid")} className="flex-1 rounded-lg border border-border bg-muted p-1 text-muted-foreground">inválido</button></div></AuthCard></div>;
}

function InviteScreen({ onActivate, onBack }: { onActivate:(u:AuthUser,t:TenantOption[],p:Record<string,ProductOption[]>)=>void; onBack:()=>void }) {
  const [status,setStatus]=useState<InviteStatus>("valid"),[pwd,setPwd]=useState(""),[confirm,setConfirm]=useState(""),[terms,setTerms]=useState(false),[loading,setLoading]=useState(false),[error,setError]=useState(""),[done,setDone]=useState(false);
  const invite={ name:"João Alves", email:"joao@byop.com", tenant:"BYOP", role:"editor" as UserRole, products:["Maestro Beton"], inviter:"Ana Martins", validUntil:"25 jun 2026" };
  const handleActivate=()=>{ setError(""); if(pwd!==confirm){setError("As senhas não coincidem.");return;} if(getPasswordStrength(pwd)==="fraca"){setError("Senha muito fraca. Use ao menos 8 caracteres com números.");return;} if(!terms){setError("Você precisa aceitar os termos para continuar.");return;} setLoading(true); setTimeout(()=>{ setLoading(false); setDone(true); const u:AuthUser={id:"u_inv",name:invite.name,email:invite.email,role:invite.role,initials:"JA"}; const t:TenantOption[]=[{id:"t1",name:"BYOP",plan:"Pro",productCount:6,lastAccess:"agora",status:"ativo"}]; const p:Record<string,ProductOption[]>={t1:[{id:"p1",name:"Maestro Beton",type:"Site Institucional",status:"Ativo",modules:6}]}; setTimeout(()=>onActivate(u,t,p),1500); },800); };
  const statusMsgs:Partial<Record<InviteStatus,string>>={ expired:`Este convite expirou em ${invite.validUntil}. Solicite um novo convite ao administrador.`, revoked:"Este convite foi revogado pelo administrador.", used:"Este convite já foi utilizado. Faça login com sua conta." };
  return <div className="flex min-h-screen items-center justify-center bg-background px-4 py-12"><AuthEnvBadge/><div className="w-full max-w-[480px]"><motion.div {...fade} className="rounded-2xl border border-border bg-card p-8 shadow-[0_24px_80px_rgba(28,28,28,.08)]"><AuthLogo/>{done?<div className="text-center"><div className="mx-auto mb-4 grid h-14 w-14 place-items-center rounded-full bg-[#ede9fe]"><CheckCircle2 size={24} className="text-primary"/></div><h2 className="font-semibold">Conta ativada com sucesso!</h2><p className="mt-1 text-sm text-muted-foreground">Redirecionando para a plataforma...</p></div>:status!=="valid"?<><div className="rounded-lg border border-destructive/20 bg-[#FDEBE8] p-4 text-sm text-destructive">{statusMsgs[status]}</div><button onClick={onBack} className="mt-4 flex w-full items-center justify-center rounded-lg bg-primary py-2.5 text-sm text-primary-foreground transition hover:bg-primary/90">Ir ao login</button></>:<><div className="mb-6 rounded-xl bg-[#ede9fe] p-4"><p className="text-sm font-semibold text-[#7c3aed]">Convite para {invite.tenant}</p><p className="mt-1 text-sm text-muted-foreground">Olá, <b>{invite.name}</b>. {invite.inviter} convidou você para operar na plataforma Aegis PMS.</p><div className="mt-3 grid gap-1.5 text-xs text-muted-foreground"><div className="flex justify-between"><span>Papel</span><b>{roleLabels[invite.role]}</b></div><div className="flex justify-between"><span>Produtos</span><b>{invite.products.join(", ")}</b></div><div className="flex justify-between"><span>Válido até</span><b>{invite.validUntil}</b></div></div></div><h2 className="mb-1 font-semibold">Definir senha e ativar conta</h2><p className="mb-4 text-sm text-muted-foreground">Escolha uma senha para acessar a plataforma.</p><div className="space-y-3"><label className="block"><span className="mb-1 block text-sm font-medium">Nova senha</span><input type="password" autoFocus value={pwd} onChange={e=>setPwd(e.target.value)} placeholder="••••••••" className="w-full rounded-lg border border-border bg-card px-3 py-2.5 text-sm outline-none transition focus:border-primary focus:ring-2 focus:ring-primary/10"/>{pwd&&<PasswordStrengthBar password={pwd}/>}</label><label className="block"><span className="mb-1 block text-sm font-medium">Confirmar senha</span><input type="password" value={confirm} onChange={e=>setConfirm(e.target.value)} placeholder="••••••••" className="w-full rounded-lg border border-border bg-card px-3 py-2.5 text-sm outline-none transition focus:border-primary focus:ring-2 focus:ring-primary/10"/></label><label className="flex cursor-pointer items-start gap-3"><input type="checkbox" checked={terms} onChange={e=>setTerms(e.target.checked)} className="mt-0.5 h-4 w-4 rounded accent-primary"/><span className="text-sm text-muted-foreground">Aceito os <span className="text-primary">Termos de Uso</span> e a <span className="text-primary">Política de Privacidade</span> da plataforma Aegis PMS.</span></label>{error&&<div className="rounded-lg border border-destructive/20 bg-[#FDEBE8] p-3 text-sm text-destructive">{error}</div>}<button onClick={handleActivate} disabled={loading||!pwd||!confirm} className="flex w-full items-center justify-center gap-2 rounded-lg bg-primary py-2.5 text-sm text-primary-foreground transition hover:bg-primary/90 disabled:opacity-50">{loading?<><Loader2 size={16} className="animate-spin"/>Ativando conta...</>:"Ativar conta"}</button></div><button onClick={onBack} className="mt-4 flex w-full items-center justify-center gap-1.5 text-sm text-muted-foreground transition hover:text-foreground"><ArrowLeft size={14}/>Voltar ao login</button></>}<div className="mt-4 flex gap-1 text-xs">{(["valid","expired","revoked","used"] as InviteStatus[]).map(s=><button key={s} onClick={()=>{setDone(false);setStatus(s);}} className="flex-1 rounded-lg border border-border bg-muted p-1 text-muted-foreground">{s}</button>)}</div></motion.div></div></div>;
}

function TenantSelectScreen({ user, tenants: ts, onSelect, onLogout }: { user:AuthUser; tenants:TenantOption[]; onSelect:(t:TenantOption)=>void; onLogout:()=>void }) {
  const [q,setQ]=useState("");
  const filtered=ts.filter(t=>t.name.toLowerCase().includes(q.toLowerCase()));
  return <div className="min-h-screen bg-background"><header className="flex items-center justify-between border-b border-border bg-card px-6 py-4 shadow-[0_1px_0_rgba(0,0,0,0.06)] dark:shadow-none"><div className="flex items-center gap-2.5"><AegisLogo size="sm"/><span className="font-semibold tracking-[-.02em]">Aegis</span><Badge tone="violet">Product OS</Badge></div><div className="flex items-center gap-3"><div className="flex items-center gap-2 rounded-xl border border-border bg-muted/40 px-3 py-1.5 text-sm"><div className="grid h-6 w-6 place-items-center rounded-full bg-primary text-primary-foreground text-xs font-semibold">{user.initials}</div><span className="text-muted-foreground hidden sm:block">{user.name}</span><Badge tone="violet">{roleLabels[user.role]}</Badge></div><button onClick={onLogout} className="flex items-center gap-1.5 rounded-xl border border-border bg-card px-3 py-1.5 text-sm transition hover:bg-muted"><LogOut size={14}/>Sair</button></div></header><main className="mx-auto max-w-3xl px-4 py-12"><motion.div {...fade}><h1 className="text-2xl font-semibold tracking-[-.02em]">Selecione seu espaço de trabalho</h1><p className="mt-1 text-sm text-muted-foreground">Você tem acesso a {ts.length} tenant{ts.length!==1?"s":""}.</p><div className="mt-6 flex items-center gap-2 rounded-xl border border-border bg-card px-3 py-2.5"><Search size={16} className="text-muted-foreground"/><input value={q} onChange={e=>setQ(e.target.value)} placeholder="Buscar tenant..." className="w-full bg-transparent text-sm outline-none"/></div><div className="mt-4 grid gap-3 md:grid-cols-2">{filtered.length===0?<EmptyState compact title="Nenhum tenant encontrado" description="Ajuste a busca."/>:filtered.map(t=><button key={t.id} onClick={()=>t.status!=="suspenso"&&onSelect(t)} disabled={t.status==="suspenso"} className="group rounded-2xl border border-border bg-card p-5 text-left transition hover:border-primary hover:shadow-[0_8px_30px_rgba(15,61,46,.08)] disabled:opacity-50"><div className="flex items-start justify-between"><div className="flex items-center gap-3"><div className="grid h-10 w-10 place-items-center rounded-xl bg-primary/10 font-semibold text-primary">{t.name.charAt(0)}</div><div><p className="font-semibold">{t.name}</p><p className="text-xs text-muted-foreground">{t.plan}</p></div></div><Badge tone={t.status==="ativo"?"green":"red"}>{t.status}</Badge></div><div className="mt-4 grid grid-cols-2 gap-2 text-xs text-muted-foreground"><span className="flex items-center gap-1"><Boxes size={12}/>{t.productCount} produtos</span><span className="flex items-center gap-1"><Clock3 size={12}/>{t.lastAccess}</span></div>{t.status==="suspenso"?<p className="mt-3 text-xs text-destructive">Tenant suspenso. Contate o suporte.</p>:<div className="mt-4 flex justify-end"><span className="text-sm text-primary opacity-0 transition group-hover:opacity-100">Entrar →</span></div>}</button>)}</div></motion.div></main></div>;
}

function ProductSelectScreen({ user, tenant, products: prods, onSelect, onBack, onLogout }: { user:AuthUser; tenant:TenantOption; products:ProductOption[]; onSelect:(p:ProductOption)=>void; onBack:()=>void; onLogout:()=>void }) {
  const [q,setQ]=useState(""),[sf,setSf]=useState("todos");
  const filtered=prods.filter(p=>(p.name+p.type).toLowerCase().includes(q.toLowerCase())&&(sf==="todos"||p.status===sf));
  const favs=filtered.filter(p=>p.isFavorite);
  const recents=filtered.filter(p=>p.isRecent&&!p.isFavorite);
  const others=filtered.filter(p=>!p.isFavorite&&!p.isRecent);
  const PCard=({p}:{p:ProductOption})=>{ const disabled=p.status==="Arquivado"||p.modules===0; return <button onClick={()=>!disabled&&onSelect(p)} disabled={disabled} className="group rounded-2xl border border-border bg-card p-5 text-left transition hover:border-primary hover:shadow-[0_8px_30px_rgba(15,61,46,.08)] disabled:cursor-not-allowed disabled:opacity-40"><div className="flex items-start justify-between gap-3"><div><div className="flex items-center gap-1.5"><p className="font-semibold">{p.name}</p>{p.isFavorite&&<Star size={12} className="fill-[#D97706] text-[#D97706]"/>}</div><p className="text-xs text-muted-foreground">{p.type}</p></div><ProductStatusBadge status={p.status}/></div><div className="mt-4 flex items-center justify-between text-xs text-muted-foreground"><span>{p.modules} módulos{p.modules===0?" · sem módulos":""}</span>{!disabled&&<span className="text-primary opacity-0 transition group-hover:opacity-100">Abrir →</span>}</div></button>; };
  const Sec=({title,icon,items}:{title:string;icon?:ReactNode;items:ProductOption[]})=>items.length===0?null:<div><div className="mb-2 flex items-center gap-1.5 text-xs font-medium text-muted-foreground">{icon}{title}</div><div className="grid gap-3 sm:grid-cols-2 xl:grid-cols-3">{items.map(p=><PCard key={p.id} p={p}/>)}</div></div>;
  return <div className="min-h-screen bg-background"><header className="flex items-center justify-between border-b border-border bg-card px-6 py-4 shadow-[0_1px_0_rgba(0,0,0,0.06)] dark:shadow-none"><div className="flex items-center gap-3"><div className="flex items-center gap-2.5"><AegisLogo size="sm"/><span className="font-semibold tracking-[-.02em]">Aegis</span></div><ChevronRight size={14} className="text-muted-foreground"/><div className="flex items-center gap-1.5"><Building2 size={14} className="text-muted-foreground"/><span className="text-sm font-medium">{tenant.name}</span></div></div><div className="flex items-center gap-2"><button onClick={onBack} className="flex items-center gap-1.5 rounded-xl border border-border bg-card px-3 py-1.5 text-sm transition hover:bg-muted"><ArrowLeft size={14}/>Trocar tenant</button><button onClick={onLogout} className="flex items-center gap-1.5 rounded-xl border border-border bg-card px-3 py-1.5 text-sm transition hover:bg-muted"><LogOut size={14}/>Sair</button></div></header><main className="mx-auto max-w-5xl px-4 py-10"><motion.div {...fade}><div className="mb-6"><h1 className="text-2xl font-semibold tracking-[-.02em]">Selecione um produto</h1><p className="mt-1 text-sm text-muted-foreground">{tenant.name} · {prods.length} produto{prods.length!==1?"s":""}</p></div><div className="mb-4 flex flex-wrap gap-2"><div className="flex min-w-[200px] flex-1 items-center gap-2 rounded-xl border border-border bg-card px-3 py-2.5"><Search size={15} className="text-muted-foreground"/><input value={q} onChange={e=>setQ(e.target.value)} placeholder="Buscar produto..." className="w-full bg-transparent text-sm outline-none"/></div>{["todos","Ativo","Pendente","Arquivado"].map(s=><button key={s} onClick={()=>setSf(s)} className={`rounded-xl border px-3 py-2 text-sm transition ${sf===s?"border-primary bg-primary/5 text-primary":"border-border bg-card text-muted-foreground hover:bg-muted"}`}>{s}</button>)}</div>{filtered.length===0?<EmptyState title="Nenhum produto encontrado" description="Ajuste os filtros ou limpe a busca."/>:<div className="space-y-6"><Sec title="Favoritos" icon={<Star size={12} className="text-[#D97706]"/>} items={favs}/><Sec title="Acessados recentemente" icon={<Clock3 size={12}/>} items={recents}/><Sec title={favs.length>0||recents.length>0?"Todos os produtos":"Produtos"} items={others}/></div>}</motion.div></main></div>;
}

