type SaveStatus = "idle" | "dirty" | "saving" | "saved" | "error";

function ScreenSkeleton() {
  return (
    <motion.div {...fade} className="space-y-5">
      <div className="space-y-2">
        <div className="h-7 w-52 animate-pulse rounded-xl bg-muted"/>
        <div className="h-4 w-80 animate-pulse rounded-lg bg-muted"/>
      </div>
      <div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4">
        {[1,2,3,4].map(i=><div key={i} className="h-28 animate-pulse rounded-2xl bg-muted"/>)}
      </div>
      <div className="grid gap-4 xl:grid-cols-[1fr_360px]">
        <div className="space-y-4">
          <div className="h-64 animate-pulse rounded-2xl bg-muted"/>
          <div className="h-32 animate-pulse rounded-2xl bg-muted"/>
        </div>
        <div className="h-80 animate-pulse rounded-2xl bg-muted"/>
      </div>
    </motion.div>
  );
}

function FloatingSaveStatus({ status, onRetry }: { status: SaveStatus; onRetry?: () => void }) {
  if (status === "idle") return null;
  const cfg: Record<Exclude<SaveStatus,"idle">, { cls: string; icon: ReactNode; text: string }> = {
    dirty:  { cls:"border-[#fef3c7] bg-[#fef3c7]/95 text-[#b45309]",  icon:<Circle size={8} className="fill-current"/>,               text:"Alterações não salvas" },
    saving: { cls:"border-border bg-card/95 text-muted-foreground",     icon:<Loader2 size={12} className="animate-spin"/>,              text:"Salvando..." },
    saved:  { cls:"border-[#dcfce7] bg-[#dcfce7]/95 text-[#15803d]",  icon:<CheckCircle2 size={12}/>,                                  text:"Salvo automaticamente" },
    error:  { cls:"border-[#fee2e2] bg-[#fee2e2]/95 text-[#dc2626]",  icon:<AlertTriangle size={12}/>,                                 text:"Erro ao salvar" },
  };
  const c = cfg[status];
  return (
    <motion.div {...fade} className={`fixed bottom-6 right-6 z-40 flex items-center gap-2 rounded-xl border px-3 py-2 text-xs shadow-[0_4px_16px_rgba(0,0,0,0.12)] backdrop-blur-sm ${c.cls}`}>
      {c.icon}{c.text}
      {status==="error"&&onRetry&&<button onClick={onRetry} className="ml-1 underline transition hover:opacity-80">Tentar novamente</button>}
    </motion.div>
  );
}

function ConfirmDialog({ title, desc, onConfirm, onCancel, danger=false, loading=false }: { title:string; desc:string; onConfirm:()=>void; onCancel:()=>void; danger?:boolean; loading?:boolean }) {
  return (
    <motion.div className="fixed inset-0 z-50 flex items-center justify-center bg-black/30 backdrop-blur-[3px] p-4" initial={{opacity:0}} animate={{opacity:1}} exit={{opacity:0}} onClick={onCancel}>
      <motion.div {...fade} className="w-full max-w-sm rounded-2xl border border-border bg-card p-6 shadow-[0_24px_80px_rgba(0,0,0,0.2)]" onClick={e=>e.stopPropagation()}>
        <h3 className="font-semibold">{title}</h3>
        <p className="mt-2 text-sm text-muted-foreground">{desc}</p>
        <div className="mt-5 flex justify-end gap-2">
          <Button onClick={onCancel}>Cancelar</Button>
          <button onClick={onConfirm} disabled={loading} className={`inline-flex items-center gap-2 rounded-lg border px-3 py-2 text-sm transition active:scale-[0.97] disabled:opacity-50 ${danger?"border-destructive bg-destructive text-destructive-foreground hover:bg-destructive/90":"border-primary bg-primary text-primary-foreground hover:bg-primary/90 shadow-[0_4px_14px_rgba(124,58,237,.25)]"}`}>
            {loading?<><Loader2 size={15} className="animate-spin"/>Processando...</>:"Confirmar"}
          </button>
        </div>
      </motion.div>
    </motion.div>
  );
}

