function AppNav({ screen, auth, go }: { screen: Screen; auth: AuthState; go: (s: Screen) => void }) {
  const navLabelMap = Object.fromEntries(nav.map(([k,,l]) => [k as string, l as string]));
  const isRoot = screen === "global";
  const isTopOnly = ["products","create"].includes(screen);
  const isProductCtx = !isRoot && !isTopOnly;
  const parentKey = parentModule[screen] as Screen | undefined;
  const moduleKey: Screen | undefined = parentKey ?? (navLabelMap[screen] ? screen as Screen : undefined);
  const moduleLabel = moduleKey ? navLabelMap[moduleKey as string] : undefined;
  const subLabel = parentKey ? screenLabels[screen] : undefined;
  const sep = <ChevronRight size={11} className="shrink-0 text-border"/>;
  const btn = (label: string, dest: Screen) => (
    <button onClick={() => go(dest)} className="transition-colors hover:text-foreground">{label}</button>
  );
  return (
    <nav className="mb-5 flex flex-wrap items-center gap-1.5 text-xs text-muted-foreground">
      {btn(auth.tenant.name, "global")}
      {!isRoot && <>{sep}</>}
      {isTopOnly && <span className="text-foreground">{screen === "create" ? "Novo Produto" : "Produtos"}</span>}
      {isProductCtx && <>
        {btn("Produtos", "products")}
        {sep}
        {btn(auth.product.name, "product")}
        {moduleLabel && <>{sep}{subLabel ? btn(moduleLabel, moduleKey as Screen) : <span className="text-foreground">{moduleLabel}</span>}</>}
        {subLabel && <>{sep}<span className="text-foreground">{subLabel}</span></>}
      </>}
    </nav>
  );
}

