export default function App() {
  const { theme, setTheme } = useTheme();
  const [authUser, setAuthUser] = useState<AuthUser | null>(null);
  const [selectedTenant, setSelectedTenant] = useState<TenantOption | null>(null);
  const [selectedProduct, setSelectedProduct] = useState<ProductOption | null>(null);
  const [authScreen, setAuthScreen] = useState<AuthScreen>("login");
  const [forgotEmail, setForgotEmail] = useState("");
  const [userTenants, setUserTenants] = useState<TenantOption[]>([]);
  const [userProducts, setUserProducts] = useState<Record<string, ProductOption[]>>({});

  const handleLogout = () => { setAuthUser(null); setSelectedTenant(null); setSelectedProduct(null); setAuthScreen("login"); setUserTenants([]); setUserProducts({}); };
  const handleLogin = (user: AuthUser, tenants: TenantOption[], products: Record<string, ProductOption[]>) => { setAuthUser(user); setUserTenants(tenants); setUserProducts(products); };
  const handleSwitchTenant = (tenantId: string) => { const t=userTenants.find(t=>t.id===tenantId); if(t){setSelectedTenant(t);setSelectedProduct(null);} };
  const handleSwitchProduct = (productId: string) => { if(!effectiveTenant) return; const p=(userProducts[effectiveTenant.id]||[]).find(p=>p.id===productId); if(p) setSelectedProduct(p); };

  const effectiveTenant = selectedTenant ?? (userTenants.length === 1 ? userTenants[0] : null);
  const tenantProds = effectiveTenant ? (userProducts[effectiveTenant.id] || []) : [];
  const activeProds = tenantProds.filter(p => p.status !== "Arquivado" && p.modules > 0);
  const effectiveProduct = selectedProduct ?? (activeProds.length === 1 ? activeProds[0] : null);

  if (!authUser) {
    if (authScreen === "forgotPassword") return <ForgotPasswordScreen onBack={() => setAuthScreen("login")} onSent={e => { setForgotEmail(e); setAuthScreen("forgotPasswordSent"); }}/>;
    if (authScreen === "forgotPasswordSent") return <ForgotPasswordSentScreen email={forgotEmail} onBack={() => setAuthScreen("login")} onResend={() => setAuthScreen("forgotPassword")} onResetDemo={() => setAuthScreen("resetPassword")}/>;
    if (authScreen === "resetPassword") return <ResetPasswordScreen onSuccess={() => setAuthScreen("login")} onBack={() => setAuthScreen("forgotPassword")}/>;
    if (authScreen === "invite") return <InviteScreen onActivate={handleLogin} onBack={() => setAuthScreen("login")}/>;
    return <LoginScreen onLogin={handleLogin} onForgot={() => setAuthScreen("forgotPassword")} onInvite={() => setAuthScreen("invite")}/>;
  }
  if (!effectiveTenant) return <TenantSelectScreen user={authUser} tenants={userTenants} onSelect={t => setSelectedTenant(t)} onLogout={handleLogout}/>;
  if (!effectiveProduct) return <ProductSelectScreen user={authUser} tenant={effectiveTenant} products={tenantProds} onSelect={p => setSelectedProduct(p)} onBack={() => setSelectedTenant(null)} onLogout={handleLogout}/>;
  const tenantSwitcherItems: SwitcherItem[] = userTenants.filter(t=>t.status==="ativo").map(t=>({ id:t.id, name:t.name, meta:t.plan }));
  const productSwitcherItems: SwitcherItem[] = tenantProds.filter(p=>p.status!=="Arquivado"&&p.modules>0).map(p=>({ id:p.id, name:p.name, meta:p.type }));
  return <AppShell auth={{ user: authUser, tenant: effectiveTenant, product: effectiveProduct }} onLogout={handleLogout} theme={theme} onThemeChange={setTheme} userTenants={tenantSwitcherItems} tenantProducts={productSwitcherItems} onSwitchTenant={handleSwitchTenant} onSwitchProduct={handleSwitchProduct}/>;
}
